import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Lab 3 · Writing transactions","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab-3-writing-transactions.md","filePath":"labs/lab-3-writing-transactions.md","lastUpdated":null}'),o={name:"labs/lab-3-writing-transactions.md"};function s(r,e,c,l,h,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="lab-3-·-writing-transactions" tabindex="-1">Lab 3 · Writing transactions <a class="header-anchor" href="#lab-3-·-writing-transactions" aria-label="Permalink to &quot;Lab 3 · Writing transactions&quot;">​</a></h1><p><strong>Deliverable:</strong> a pull request: certificate issuing and verification, done properly · <strong>Time:</strong> two hours</p><p>Reading a chain is easy. Writing to one is where dApps are actually judged, because a transaction can fail in a dozen ways and most of them happen after the user has committed. This lab is about the whole lifecycle, and about being honest with the person waiting.</p><h2 id="the-job" tabindex="-1">The job <a class="header-anchor" href="#the-job" aria-label="Permalink to &quot;The job&quot;">​</a></h2><p>Rebuild the College&#39;s certificate flow so that issuing and verifying a certificate is something a non-technical user could complete without help.</p><p><strong>Issuing.</strong> The issuer picks a file from their computer, names the course, and issues to a holder&#39;s address. The file is hashed <strong>in the browser</strong> — it never leaves the machine.</p><p><strong>Verifying.</strong> Anyone pastes or drops a file and gets a verdict: is this the document behind certificate #N, is the certificate still valid, and who issued it.</p><p><strong>Revoking.</strong> The issuer can revoke with a reason, and the interface makes the consequence clear before they confirm: the certificate is not deleted, it is permanently marked.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>[ ] File hashing happens client-side; files are never uploaded anywhere.</li><li>[ ] A 50 MB file does not freeze the tab.</li><li>[ ] Before sending, the transaction is <strong>simulated</strong>; a failure that simulation catches never reaches the wallet.</li><li>[ ] Every state is visible and distinct: idle, simulating, waiting for the wallet, pending on chain, confirmed, failed.</li><li>[ ] A user rejecting in MetaMask returns to idle with no scary error — it is not an error, it is a decision.</li><li>[ ] A revert shows the <strong>decoded custom error</strong> as a sentence. <code>0x82b42900</code> is not an error message.</li><li>[ ] Verification tells the difference between three cases: wrong document, right document but revoked certificate, and no such certificate.</li><li>[ ] The revoke control requires confirmation and states that revocation is permanent.</li><li>[ ] CI green.</li></ul><h2 id="technical-requirements" tabindex="-1">Technical requirements <a class="header-anchor" href="#technical-requirements" aria-label="Permalink to &quot;Technical requirements&quot;">​</a></h2><p><strong>Simulate first.</strong> <code>publicClient.simulateContract</code> before <code>writeContract</code>. It costs one RPC call and catches most reverts before the user signs. This is the single habit that most separates a professional dApp from a student one.</p><p><strong>Decode errors.</strong> The contracts use custom errors: <code>NotTheIssuer()</code>, <code>AlreadyRevoked()</code>, <code>NotAResident()</code>. Map them to sentences. <code>app/src/tx.js</code> already does some of this — extend it rather than writing a second version.</p><p><strong>Hash large files without blocking.</strong> Read as an ArrayBuffer and hash the bytes. If the UI freezes on a big file, you are doing it on the main thread in one go.</p><p><strong>Idempotence.</strong> Double-clicking the issue button must not send two transactions. Disable it, and say in your PR what would happen on chain if you had not.</p><h2 id="the-interesting-question" tabindex="-1">The interesting question <a class="header-anchor" href="#the-interesting-question" aria-label="Permalink to &quot;The interesting question&quot;">​</a></h2><p>A certificate hash proves a document has not changed since it was issued. It does <strong>not</strong> prove the issuer was entitled to issue it, and it does not stop them issuing the same certificate to fifty people.</p><p>In your PR, answer in a short paragraph: <strong>what does your verification screen actually tell a sceptical employer, and what does it not?</strong> Then make sure the interface does not overclaim. Wording like &quot;✓ Verified&quot; invites a reader to believe more than you have proven.</p><h2 id="common-ways-this-goes-wrong" tabindex="-1">Common ways this goes wrong <a class="header-anchor" href="#common-ways-this-goes-wrong" aria-label="Permalink to &quot;Common ways this goes wrong&quot;">​</a></h2><ul><li><strong>Hashing the filename or a data URL</strong> instead of the file bytes. Works consistently for the person who wrote it and for nobody else.</li><li><strong>Hashing text instead of bytes.</strong> A <code>.docx</code> read as text hashes differently every time on some platforms. Pick bytes and be consistent.</li><li><strong>Treating rejection as failure.</strong> The most common wallet outcome is &quot;user changed their mind&quot;. Red error toasts for that are a tell.</li><li><strong>A spinner with no timeout.</strong> If the transaction never confirms, what does the user see in two minutes? Decide.</li><li><strong>Optimistic UI that lies.</strong> Showing the certificate as issued before it is mined, with no rollback when it reverts, is worse than being slow.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No contract changes — <code>CertificateRegistry</code> stays as it is. No file storage: the document stays on the user&#39;s machine, which is the design.</p><h2 id="hand-in" tabindex="-1">Hand in <a class="header-anchor" href="#hand-in" aria-label="Permalink to &quot;Hand in&quot;">​</a></h2><ol><li>The PR, CI green, reviewed and approved.</li><li>Your review of someone else&#39;s PR. Specifically: reject in MetaMask, and try to issue a certificate you are not entitled to issue. Report what you saw.</li><li>An incident write-up if anything broke.</li></ol>',24)])])}const f=t(o,[["render",s]]);export{g as __pageData,f as default};
